package cn.balltv.portal;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class LiveStateTest {
 final long now=Events.epoch("2026-11-09 23:00:00");
 Feeds.Match m(String source,String at,String state,String sport)throws Exception{Feeds.Match m=new Feeds.Match();m.source=source;m.id="id";m.title="甲 vs 乙";m.home="甲";m.away="乙";m.sport=sport;m.time=at;m.status="live";m.eventState=state;m.room="r";m.raw=new JSONObject();return m;}
 @Before public void clear(){synchronized(LiveState.ENDED){LiveState.ENDED.clear();}}
 @Test public void noonAndEighteenOclockGamesAreGoneAtTwentyThree()throws Exception{for(String at:new String[]{"2026-11-09 12:00","2026-11-09 18:00"})for(String sport:new String[]{"1","2"}){Feeds.Match m=m("74体育/球吧",at,"live",sport);assertEquals(LiveState.Phase.HIDE,LiveState.phase(m,Arrays.asList(m),now));}}
 @Test public void gameFinishedOverridesRoomStillOnlineAcrossSources()throws Exception{Feeds.Match ended=m("看球通","2026-11-09 20:30","finished","1"),room=m("74体育/球吧","2026-11-09 20:30","live","1");assertTrue(LiveState.admit(Arrays.asList(ended,room),now).isEmpty());}
 @Test public void completionSurvivesCatalogRemovalAndProcessRestore()throws Exception{Feeds.Match ended=m("看球通","2026-11-09 20:30","finished","1"),room=m("74体育/球吧","2026-11-09 20:30","live","1");LiveState.prepare(Arrays.asList(ended),now);String json=LiveState.encodeEnded();LiveState.ENDED.clear();LiveState.restoreEnded(json,now+60000);assertEquals(LiveState.Phase.HIDE,LiveState.phase(room,Arrays.asList(room),now+60000));}
 @Test public void tomorrowRematchIsNotSuppressedByTodayCompletion()throws Exception{Feeds.Match ended=m("看球通","2026-11-09 20:30","finished","1");LiveState.prepare(Arrays.asList(ended),now);Feeds.Match tomorrow=m("看球通","2026-11-10 20:30","live","1");assertEquals(LiveState.Phase.LIVE,LiveState.phase(tomorrow,Arrays.asList(tomorrow),Events.epoch("2026-11-10 21:00")));}
 @Test public void noStartOrAnonymousStreamerCannotBeClaimedAsMatchLive()throws Exception{Feeds.Match unknown=m("鲸鱼","","live","2");assertEquals(LiveState.Phase.HIDE,LiveState.phase(unknown,Arrays.asList(unknown),now));unknown=m("鲸鱼","2026-11-09 22:30","live","2");unknown.home="";unknown.away="";assertEquals(LiveState.Phase.HIDE,LiveState.phase(unknown,Arrays.asList(unknown),now));}
 @Test public void nearbyPreparationIsSoonButFarFutureIsHidden()throws Exception{Feeds.Match soon=m("看球通","2026-11-09 23:30","upcoming","1");assertEquals(LiveState.Phase.SOON,LiveState.phase(soon,Arrays.asList(soon),now));soon.time="2026-11-10 02:00";assertEquals(LiveState.Phase.HIDE,LiveState.phase(soon,Arrays.asList(soon),now));}
 @Test public void unknownStatusRemainsVisibleWithoutClaimingLive()throws Exception{Feeds.Match guessed=m("JRKAN","2026-11-09 22:30","","1");assertEquals(LiveState.Phase.CHECKING,LiveState.phase(guessed,Arrays.asList(guessed),now));Feeds.Match match=m("看球通","2026-11-09 22:30","live","1");assertEquals(LiveState.Phase.LIVE,LiveState.phase(guessed,Arrays.asList(guessed,match),now));}
 @Test public void coffeeEpochCorrectionNeedsTwoIndependentFamilies()throws Exception{Feeds.Match coffee=m("咖啡","2026-11-09 15:00","live","1"),a=m("看球通","2026-11-09 23:00","live","1"),mirror=m("So米","2026-11-09 23:00","live","1"),b=m("74体育/球吧","2026-11-09 23:00","live","1");LiveState.prepare(Arrays.asList(coffee,a,mirror),now);assertEquals(Events.epoch("2026-11-09 15:00"),Events.epoch(coffee.time));LiveState.prepare(Arrays.asList(coffee,a,b),now);assertEquals(Events.epoch("2026-11-09 23:00"),Events.epoch(coffee.time));}
 @Test public void longSportsUseDifferentWindowAndUnknownCodeIsNotInvented()throws Exception{Feeds.Match tennis=m("看球通","2026-11-09 18:30","live","3");assertEquals(LiveState.Phase.LIVE,LiveState.phase(tennis,Arrays.asList(tennis),now));assertEquals("finished",LiveState.matchCode("1",7));assertEquals("upcoming",LiveState.matchCode("2",1));assertEquals("",LiveState.matchCode("esports",7));}
 @Test public void futureSecondsAreStillPreparationNotLive()throws Exception{Feeds.Match future=m("看球通","2026-11-09 23:00:30","live","1");assertEquals(LiveState.Phase.SOON,LiveState.phase(future,Arrays.asList(future),now));}
 @Test public void singleListKeepsLiveBeforeSoonWithoutPopularityOrTimeSort()throws Exception{Feeds.Match a=m("看球通","2026-11-09 22:20","live","1"),b=m("74体育/球吧","2026-11-09 22:00","live","1"),future=m("So米","2026-11-09 23:30","upcoming","2");b.home="丙";future.home="丁";ArrayList<Events.Group> groups=Events.group(Arrays.asList(future,a,b),false);LiveState.sort(groups,now);assertEquals(a,groups.get(0).lead());assertEquals(b,groups.get(1).lead());assertEquals(future,groups.get(2).lead());}
 @Test public void correctedStartSurvivesSavedRecordParsing()throws Exception{Feeds.Match coffee=m("咖啡","2026-11-09 15:00","live","1");coffee.raw=new JSONObject("{match_id:123,room_id:'r',home_team:'甲',away_team:'乙',status:'live'}");Feeds.Match a=m("看球通","2026-11-09 23:00","live","1"),b=m("74体育/球吧","2026-11-09 23:00","live","1");LiveState.prepare(Arrays.asList(coffee,a,b),now);Feeds.Page restored=Feeds.parse("咖啡","live",new JSONObject().put("data",new JSONArray().put(coffee.raw)));assertEquals(Events.epoch("2026-11-09 23:00"),Events.epoch(restored.items.get(0).time));}
}
